let state={page:'dashboard',resourceFilter:'All',providerFilter:'Service providers',requests:[
 {id:'YN-1042',title:'Introduction to a CA in Mumbai',desc:'Need support with startup tax and MCA filings.',status:'In review',date:'2 Sep',owner:'Priya · Portfolio Operations'},
 {id:'YN-1038',title:'Series A readiness review',desc:'Requesting a review of our preparation checklist.',status:'In progress',date:'30 Aug',owner:'Aman · Investment Team'}],rsvps:{1:false},tour:0};
const content=document.getElementById('content'), title=document.getElementById('pageTitle');

function head(kicker,h,desc,actions=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${h}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function metric(icon,label,value,detail){return `<div class="card metric"><div class="icon-box">${svg(icon)}</div><div><span>${label}</span><strong>${value}</strong><small class="muted">${detail}</small></div></div>`}
function resourceCard(r){return `<article class="card resource-card" data-resource="${r.id}"><span class="tag">${r.cat.toUpperCase()} · ${r.type}</span><h3>${r.title}</h3><p>${r.desc}</p><div class="meta">${r.review}</div><div class="card-actions"><button class="btn primary" data-action="download" data-id="${r.id}">${svg('download')} Download</button><button class="btn ghost" data-action="resource-detail" data-id="${r.id}">View details</button></div></article>`}
function dashboard(){return head('GOOD MORNING, ARUN','Here’s what matters today','Relevant support for Exponent Energy, without the noise.',`<button class="btn ghost" data-goto="resources">Browse resources</button>`) +
 `<div class="grid cols-4">${metric('library','Resources available','41','Across 6 curated categories')}${metric('users','Vetted connections','27','Consent verified by YourNest')}${metric('send','Open requests',state.requests.length,'1 awaiting internal review')}${metric('map','Active playbook','Day 38','Operations · 42% complete')}</div>
 <section class="section"><div class="notice"><strong>Published for Exponent Energy:</strong> EV Compliance Starter Pack is ready to review. <button class="text-btn" data-action="resource-detail" data-id="8">Open resource →</button></div></section>
 <div class="grid cols-2"><section class="card"><div class="section-title"><h2>Continue your playbook</h2><button class="text-btn" data-goto="playbooks">View playbooks →</button></div><div class="playbook-hero"><div><span class="eyebrow">100-DAY PLAYBOOK</span><h3>Operations · Days 31–60</h3><p class="muted">3 of 7 actions completed in this phase</p><button class="btn primary" data-goto="playbooks">Continue where you left off</button></div><div class="progress-ring"><strong>42%</strong></div></div></section>
 <section class="card"><div class="section-title"><h2>Upcoming</h2><button class="text-btn" data-goto="events">All events →</button></div><div class="event-card"><div class="event-date"><span>SEP</span><strong>12</strong></div><div><h3>Founder Day 2026</h3><p>Gurugram · 10:00 AM</p><span class="audience">Invited for you</span></div><button class="btn primary" data-action="rsvp" data-id="1">RSVP</button></div></section></div>
 <div class="grid cols-2 section"><section class="card"><div class="section-title"><h2>Quick access</h2></div><div class="quick">${resources.slice(0,4).map(r=>`<button data-action="resource-detail" data-id="${r.id}">${svg('file')} ${r.title}</button>`).join('')}</div></section><section class="card"><div class="section-title"><h2>Recent activity</h2></div><div class="activity"><div class="activity-row"><i class="dot"></i><div><strong>ATS Selection Guide downloaded</strong><small>Hiring support resource</small></div><time>Today</time></div><div class="activity-row"><i class="dot"></i><div><strong>CA introduction assigned</strong><small>Priya is reviewing your request</small></div><time>Yesterday</time></div><div class="activity-row"><i class="dot"></i><div><strong>Operations checklist completed</strong><small>100-Day Playbook</small></div><time>3 days</time></div></div></section></div>`}
function resourcePage(){let cats=['All','Legal','Finance','Hiring','Operations','Compliance','Fundraising'];let list=state.resourceFilter==='All'?resources:resources.filter(r=>r.cat===state.resourceFilter);return head('CURATED KNOWLEDGE','Resource Library','Trusted templates, guides and reference material for company-building.',`<button class="btn ghost" data-action="suggest-resource">Can’t find it?</button>`) + `<div class="filters">${cats.map(c=>`<button class="chip ${c===state.resourceFilter?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div><div class="grid cols-3">${list.map(resourceCard).join('')}</div>`}
function connectPage(){return head('NETWORK','Connect','Request a warm introduction to a vetted expert, provider or founder.',`<button class="btn primary" data-action="connect-help">Help me choose</button>`) + `<div class="tabs"><button class="tab active">Service providers</button><button class="tab">Peer founders · Opt-in</button></div><div class="notice">Contact details remain private until YourNest approves and coordinates the introduction.</div><div class="grid cols-3">${providers.map(p=>`<article class="card provider-card"><div class="provider-head"><div class="avatar">${p.initials}</div><div><h3>${p.name}</h3><p>${p.role}</p></div></div><span class="tag">${p.org.toUpperCase()}</span><div class="skills">${p.skills.map(s=>`<span>${s}</span>`).join('')}</div><p>${p.why}</p><button class="btn primary wide" data-action="intro" data-id="${p.id}">${svg('send')} Request introduction</button></article>`).join('')}</div>`}
function requestsPage(){return head('NETWORK','Requests','Ask for support and follow every step through resolution.') + `<div class="split"><section><div class="section-title"><h2>Your requests</h2><span class="muted">${state.requests.length} open</span></div>${state.requests.map((r,i)=>`<button class="card request-card wide" data-action="request-detail" data-id="${i}"><i class="dot"></i><div><h3>${r.title}</h3><p>${r.id} · ${r.desc}</p><small class="muted">Owner: ${r.owner}${r.source?` · From resource: ${r.source}`:''}</small></div><span class="status ${r.status==='In review'?'review':'progress'}">${r.status}</span></button>`).join('')}</section><aside class="card"><div class="section-title"><h2>How routing works</h2></div><div class="timeline"><div class="timeline-item"><strong>1. You submit</strong><small>Company and request type are recorded.</small></div><div class="timeline-item"><strong>2. We route</strong><small>Your current relationship team or specialist receives it.</small></div><div class="timeline-item"><strong>3. You track</strong><small>Owner, status and founder-visible updates stay in one place.</small></div><div class="timeline-item"><strong>4. We resolve</strong><small>Resolution and history remain auditable.</small></div></div></aside></div>`}
function playbooksPage(){let phases=[['Foundation','Days 1–30','Complete',['Onboarding essentials','Founder alignment note','Initial operating cadence']],['Operations','Days 31–60','Active · Day 38',['MIS reporting template (resource only)','Publish core HR policy','Finalise ESOP policy','Set quarterly OKRs']],['Growth','Days 61–80','Upcoming',['Sales pipeline review','Customer insight synthesis','Leadership hiring plan']],['Fundraise readiness','Days 81–100','Upcoming',['Evidence room checklist','Narrative readiness','Investor process plan']]];return head('STRUCTURED GUIDANCE','Playbooks','Reusable guidance plus active journeys that YourNest and founders can work through together.',`<button class="btn ghost" data-action="playbook-catalog">Browse all playbooks</button>`) + `<section class="card playbook-hero"><div><span class="eyebrow">ACTIVE FOR EXPONENT ENERGY</span><h2>100-Day Founder Playbook</h2><p class="muted">Started 26 July · YourNest owner: Aman Verma · Next check-in 6 September</p></div><div class="progress-ring"><strong>42%</strong></div></section><section class="section accordion">${phases.map((x,i)=>`<div class="phase ${i===1?'open':''}"><button class="phase-head" data-action="phase"><span class="phase-no">${i+1}</span><span><strong>${x[0]}</strong><small>${x[1]}</small></span><span class="status ${i===0?'resolved':i===1?'progress':'upcoming'}">${x[2]}</span><span>⌄</span></button><div class="phase-body">${x[3].map((t,j)=>`<div class="task"><span>${i===0||j<1?svg('check'):svg('clock')} ${t}</span><a href="#" data-action="task">${i===0?'Completed':'Open →'}</a></div>`).join('')}</div></div>`).join('')}</section><section class="section"><div class="section-title"><h2>Reference playbooks</h2><span class="muted">Read-only guides in the Resource Library</span></div><div class="grid cols-3">${['GCC market entry guide','Sales operating case study','Dubai expansion guide'].map((x,i)=>`<article class="card resource-card"><span class="tag">REFERENCE PLAYBOOK</span><h3>${x}</h3><p>${['Market selection, entity setup and operating considerations.','A practical account of a portfolio sales-engagement process.','A concise orientation to launch planning and local support.'][i]}</p><div class="meta">Approved resource</div><button class="btn ghost">View guide →</button></article>`).join('')}</div></section>`}
function eventsPage(){let ev=[{id:1,d:'12',m:'SEP',title:'Founder Day 2026',meta:'Gurugram · 10:00 AM–4:30 PM',desc:'Founder conversations, operator sessions and peer learning.',aud:'Invited for you'},{id:2,d:'18',m:'SEP',title:'Finance Office Hours',meta:'Online · 4:00–5:00 PM',desc:'Open questions on reporting, finance controls and planning.',aud:'Portfolio-wide'},{id:3,d:'03',m:'OCT',title:'Series A Readiness Clinic',meta:'Online · 3:00–4:30 PM',desc:'A working session for founders preparing an institutional round.',aud:'Selected companies'}];return head('ENGAGEMENT','Events','Invitations, office hours and founder programmes in one place.',`<button class="btn ghost" data-action="calendar">Add portal events to calendar</button>`) + `<div class="tabs"><button class="tab active">Upcoming</button><button class="tab">My RSVPs</button><button class="tab">Recordings</button></div><section>${ev.map(e=>`<article class="card event-card"><div class="event-date"><span>${e.m}</span><strong>${e.d}</strong></div><div><h3>${e.title}</h3><p>${e.meta}</p><p>${e.desc}</p><span class="audience">${e.aud}</span></div><button class="btn ${state.rsvps[e.id]?'ghost':'primary'}" data-action="rsvp" data-id="${e.id}">${state.rsvps[e.id]?'✓ Going':'RSVP'}</button></article>`).join('')}</section>`}
const pages={dashboard,resources:resourcePage,connect:connectPage,requests:requestsPage,playbooks:playbooksPage,events:eventsPage};
function render(page=state.page){state.page=page;title.textContent={dashboard:'Dashboard',resources:'Resource Library',connect:'Network / Connect',requests:'Network / Requests',playbooks:'Playbooks',events:'Events',updates:'Sector Updates',admin:'Admin workspace'}[page];document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===page));content.innerHTML=pages[page]();document.querySelector('.sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});}
function modal(titleText,body,submit='Submit request',onSubmit){const m=document.getElementById('modal');m.innerHTML=`<div class="modal"><div class="modal-head"><div><span class="eyebrow">FOUNDER PORTAL</span><h2>${titleText}</h2></div><button class="icon-btn" data-action="close-modal">×</button></div><form id="modalForm" class="form"><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="btn ghost" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">${submit}</button></div></form></div>`;m.classList.remove('hidden');document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();onSubmit?.(new FormData(e.target));m.classList.add('hidden')}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
const helpCategory={Legal:'Legal or compliance support',Compliance:'Legal or compliance support',Finance:'Finance or MIS support',Hiring:'Hiring or HR support',Fundraising:'Fundraising support',Operations:'Technology or operational support'};
function requestModal(prefill='',opts={}){const types=['Introduction request','Legal or compliance support','Finance or MIS support','Hiring or HR support','Fundraising support','Customer or business development','Technology or operational support','Resource request','Other'];const src=opts.resource;modal('Create a new request',`${src?`<div class="request-context"><div><small>Company</small><strong>Exponent Energy</strong></div><div><small>Originating resource</small><strong>${src.title}</strong></div></div>`:''}<div class="row"><label>Request type<select name="type">${types.map(t=>`<option${t===opts.type?' selected':''}>${t}</option>`).join('')}</select></label><label>Priority<select name="priority"><option>Normal</option><option>Important</option><option>Urgent</option></select></label></div><label>What do you need?<input name="subject" value="${prefill}" placeholder="A concise subject" required></label><label>Context<textarea name="context" placeholder="What outcome are you looking for? Include any useful context." required>${opts.context||''}</textarea></label><small class="muted">This will be routed using Exponent Energy’s current YourNest assignment and the selected request category.</small>`,'Submit request',fd=>{state.requests.unshift({id:'YN-'+(1043+state.requests.length),title:fd.get('subject'),desc:fd.get('context'),category:fd.get('type'),source:src?src.title:'',status:'In review',date:'Today',owner:'Routing in progress'});document.getElementById('requestBadge').textContent=state.requests.length;toast('Request submitted and queued for routing');render('requests')})}
function resourceHelp(r){requestModal(`Help applying: ${r.title}`,{resource:r,type:helpCategory[r.cat]||'Other',context:`We are working with the ${r.title} (${r.type}) and would like YourNest support to apply it to Exponent Energy. Specifically: `})}
function detail(r){modal(r.title,`<span class="tag">${r.cat.toUpperCase()} · ${r.type}</span><p>${r.desc}</p><div class="notice"><strong>Content assurance:</strong> ${r.review}. Resource versions are checksum-protected and older versions remain auditable.</div><div class="help-handoff"><div><strong>Need help applying this?</strong><small>Your request is prefilled with this resource and routed to Exponent Energy’s YourNest team.</small></div><button type="button" class="btn ghost" data-action="resource-help" data-id="${r.id}">${svg('send')} Ask YourNest for help</button></div><h3>Who can see this?</h3><p class="muted">${r.id===8?'Exponent Energy founders and assigned YourNest staff':'Approved portfolio founders, subject to role and stage rules.'}</p>`,'Download current version',()=>toast(`${r.title} download simulated`))}
document.getElementById('loginForm').onsubmit=e=>{e.preventDefault();document.getElementById('login').classList.add('hidden');document.getElementById('app').classList.remove('hidden');render()};document.getElementById('logout').onclick=()=>{document.getElementById('app').classList.add('hidden');document.getElementById('login').classList.remove('hidden')};
document.addEventListener('click',e=>{const el=e.target.closest('[data-page],[data-goto],[data-action],[data-filter]');if(!el)return;if(el.dataset.page||el.dataset.goto){render(el.dataset.page||el.dataset.goto);return}if(el.dataset.filter){state.resourceFilter=el.dataset.filter;render('resources');return}let a=el.dataset.action;if(a==='new-request'||a==='suggest-resource')requestModal();if(a==='close-modal')document.getElementById('modal').classList.add('hidden');if(a==='resource-help')resourceHelp(resources.find(r=>r.id==el.dataset.id));if(a==='resource-detail')detail(resources.find(r=>r.id==el.dataset.id));if(a==='download')toast(`${resources.find(r=>r.id==el.dataset.id).title} download simulated`);if(a==='intro'){let x=providers.find(p=>p.id==el.dataset.id);requestModal(`Introduction to ${x.name} · ${x.role}`)}if(a==='connect-help')requestModal('Help finding the right expert or provider');if(a==='request-detail'){let r=state.requests[el.dataset.id];modal(r.title,`<span class="status ${r.status==='In review'?'review':'progress'}">${r.status}</span><p>${r.desc}</p>${r.source?`<div class="notice"><strong>Originating resource:</strong> ${r.source}${r.category?` · ${r.category}`:''}</div>`:''}<h3>Current owner</h3><p>${r.owner}</p><div class="timeline"><div class="timeline-item"><strong>Request submitted</strong><small>${r.date} · by Arun Vinayak</small></div><div class="timeline-item"><strong>Routing reviewed</strong><small>Matched using company and category</small></div></div><label>Add a message<textarea placeholder="Share an update with the YourNest team"></textarea></label>`,'Send update',()=>toast('Update added to request'))}if(a==='phase')el.parentElement.classList.toggle('open');if(a==='rsvp'){state.rsvps[el.dataset.id]=!state.rsvps[el.dataset.id];toast(state.rsvps[el.dataset.id]?'RSVP confirmed':'RSVP withdrawn');render('events')}if(a==='close-drawer'){toggleDrawer(false)}if(a==='mark-read'){document.querySelectorAll('.notification-item').forEach(n=>n.classList.remove('unread'));toast('All notifications marked as read')}if(a==='calendar')toast('Calendar connection simulated');if(a==='task')toast('Playbook task opened')});
function toggleDrawer(open){document.getElementById('notificationPanel').classList.toggle('open',open);document.getElementById('scrim').classList.toggle('open',open)}document.getElementById('notifyBtn').onclick=()=>toggleDrawer(true);document.getElementById('scrim').onclick=()=>toggleDrawer(false);document.getElementById('menu').onclick=()=>document.querySelector('.sidebar').classList.add('open');
document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){state.resourceFilter='All';render('resources');let q=e.target.value.toLowerCase();document.querySelectorAll('.resource-card').forEach(c=>c.style.display=c.textContent.toLowerCase().includes(q)?'flex':'none');toast(`Showing portal results for “${e.target.value}”`)}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('globalSearch').focus()}if(e.key==='Escape'){document.getElementById('modal').classList.add('hidden');toggleDrawer(false)}});
const tourSteps=[['The founder-first dashboard','Only actionable portal information appears here—resources, active playbooks, requests, events and the assigned relationship team. No DealScreener or performance metrics.','dashboard'],['Curated Resource Library','Searchable, versioned and audience-controlled knowledge. MIS is a downloadable template only, never a live integration.','resources'],['Network → Connect','Vetted providers and optional peers. Contact information remains private until a warm introduction is approved.','connect'],['Network → Requests','Every support need has a company, owner, status, messages and reassignment history.','requests'],['Reference and interactive Playbooks','Read-only guides can live as resources; active company journeys track sections, participants and progress.','playbooks'],['Events and two-way communication','Targeted invitations, RSVP, reminders, nudges and recordings complete the engagement loop.','events']];
function showTour(){let [h,pText,page]=tourSteps[state.tour];render(page);document.getElementById('tourCount').textContent=`${state.tour+1} / ${tourSteps.length}`;document.getElementById('tourTitle').textContent=h;document.getElementById('tourText').textContent=pText;document.getElementById('tour').classList.remove('hidden');document.getElementById('tourNext').textContent=state.tour===tourSteps.length-1?'Finish':'Next →'}document.getElementById('tourBtn').onclick=()=>{state.tour=0;showTour()};document.getElementById('tourExit').onclick=()=>document.getElementById('tour').classList.add('hidden');document.getElementById('tourNext').onclick=()=>{if(state.tour===tourSteps.length-1){document.getElementById('tour').classList.add('hidden');toast('Stakeholder walkthrough complete')}else{state.tour++;showTour()}};
